<?php /** Native WP Job Manager detail route. */ get_header(); ?>
<main id="main-content" class="jsc-job-detail jsc-detail"><div class="jsc-container">
<?php while ( have_posts() ) : the_post(); $jsc_photos = jsc_gallery_photos( get_the_ID() ); ?>
<?php jsc_breadcrumbs( 'jobs', 'All Jobs', 'Job Detail' ); get_template_part( 'template-parts/project-detail-summary' ); ?>
<div class="jsc-detail-columns"><article class="jsc-prose jsc-job-description">
<?php if ( function_exists( 'wpjm_the_job_description' ) ) { wpjm_the_job_description(); } else { echo wp_kses_post( wpautop( get_the_content() ) ); } ?>
<section class="jsc-job-location"><h2>Location</h2><p><?php echo esc_html( get_post_meta( get_the_ID(), '_job_location', true ) ); ?>. Join the <?php echo esc_html( get_post_meta( get_the_ID(), '_company_name', true ) ); ?> team and bring thoughtful hospitality to every guest interaction. Location, working arrangements and the recruitment process can be discussed with the team when you apply.</p></section>
</article>
<aside class="jsc-job-sidebar" aria-label="Company information">
<?php $rating = get_post_meta( get_the_ID(), 'jsc_rating', true ); if ( is_numeric( $rating ) ) : ?><section class="jsc-sidebar-box"><h2>Staff Rating</h2><div class="jsc-rating" aria-label="<?php echo esc_attr( 'Design reference staff rating: ' . $rating . ' out of 5' ); ?>"><span aria-hidden="true"><?php for ( $star = 1; $star <= 5; $star++ ) : ?><span class="<?php echo $star > max( 0, min( 5, (float) $rating ) ) ? 'jsc-empty-star' : ''; ?>"><?php echo $star <= (float) $rating ? '★' : '☆'; ?></span> <?php endfor; ?></span> <b><?php echo esc_html( number_format_i18n( (float) $rating, 1 ) ); ?></b></div></section><?php endif; ?>
<section class="jsc-sidebar-box"><h2>Company Photos</h2><button type="button" class="jsc-gallery-open" aria-label="<?php echo esc_attr( 'View ' . count( $jsc_photos ) . ' company photos' ); ?>"><img src="<?php echo esc_url( $jsc_photos[0]['url'] ); ?>" width="260" height="260" alt="<?php echo esc_attr( $jsc_photos[0]['alt'] ); ?>"><?php if ( count( $jsc_photos ) > 1 ) : ?><span aria-hidden="true">+<?php echo esc_html( count( $jsc_photos ) - 1 ); ?></span><?php endif; ?></button></section>
</aside></div>
<dialog class="jsc-gallery-dialog" aria-labelledby="gallery-title"><div class="jsc-gallery-toolbar"><h2 id="gallery-title">Company Photos</h2><button class="jsc-gallery-close" type="button" aria-label="Close photos">×</button></div><img class="jsc-gallery-large" src="<?php echo esc_url( $jsc_photos[0]['url'] ); ?>" alt="<?php echo esc_attr( $jsc_photos[0]['alt'] ); ?>"><div class="jsc-gallery-thumbnails"><?php foreach ( $jsc_photos as $photo ) : ?><button type="button" data-photo="<?php echo esc_url( $photo['url'] ); ?>" data-alt="<?php echo esc_attr( $photo['alt'] ); ?>"><img src="<?php echo esc_url( $photo['url'] ); ?>" alt="<?php echo esc_attr( $photo['alt'] ); ?>" width="90" height="70" loading="lazy"></button><?php endforeach; ?></div></dialog>
<?php $current_job = get_the_ID(); endwhile; ?>
<section class="jsc-related-jobs" aria-labelledby="other-jobs-title"><h2 class="jsc-title" id="other-jobs-title">Other Jobs</h2><?php jsc_cards( jsc_jobs( array( 'posts_per_page' => 6, 'post__not_in' => array( $current_job ) ) ), 'job' ); ?></section>
</div></main><?php get_footer(); ?>
